package db_test

// A5/A6: the Go side must read a database written by the Python
// implementation. The fixture is generated by
// designs/go-rewrite/make-reference-db.py from the production encoders, so it
// carries every awkward case rather than a guess at the format:
//
//   - framed + zstd and framed + raw CompressedText values
//   - legacy unframed plaintext stored as TEXT and as BLOB
//   - every ITEM_TYPE and ITEM_STATUS code
//   - Uuid16 columns as 16 raw bytes, with nullable and non-nullable ids
//
// A failure here means a user upgrading to the Go build would lose or
// misinterpret existing history, which is why it gates P1.

import (
	"database/sql"
	"encoding/json"
	"os"
	"path/filepath"
	"strings"
	"testing"

	_ "modernc.org/sqlite"

	"github.com/Brinmon/omnigent/go/internal/db"
)

const (
	referenceDB = "../../testdata/reference.db"
	enumDump    = "../../testdata/enum_codes.json"
	idDump      = "../../testdata/reference_ids.json"
)

// openReference opens the fixture read-only so a buggy test cannot corrupt the
// checked-in reference data.
func openReference(t *testing.T) *sql.DB {
	t.Helper()
	if _, err := os.Stat(referenceDB); err != nil {
		t.Fatalf("missing reference fixture %s; regenerate it with "+
			"`python designs/go-rewrite/make-reference-db.py`: %v", referenceDB, err)
	}
	abs, err := filepath.Abs(referenceDB)
	if err != nil {
		t.Fatalf("resolve fixture path: %v", err)
	}
	// mode=ro keeps the fixture immutable; the generator owns its contents.
	conn, err := sql.Open("sqlite", "file:"+filepath.ToSlash(abs)+"?mode=ro")
	if err != nil {
		t.Fatalf("open reference db: %v", err)
	}
	t.Cleanup(func() { _ = conn.Close() })
	if err := conn.Ping(); err != nil {
		t.Fatalf("ping reference db: %v", err)
	}
	return conn
}

type referenceIDs struct {
	Conversations map[string]string `json:"conversations"`
	Items         map[string]string `json:"items"`
}

func loadReferenceIDs(t *testing.T) referenceIDs {
	t.Helper()
	raw, err := os.ReadFile(idDump)
	if err != nil {
		t.Fatalf("read %s: %v", idDump, err)
	}
	var ids referenceIDs
	if err := json.Unmarshal(raw, &ids); err != nil {
		t.Fatalf("parse %s: %v", idDump, err)
	}
	return ids
}

// TestReferenceDBIsReadable is the A5 smoke check: the fixture opens and every
// table the rewrite depends on has the rows the generator wrote.
func TestReferenceDBIsReadable(t *testing.T) {
	conn := openReference(t)

	cases := map[string]int{
		"agents":             2,
		"conversations":      4,
		"conversation_items": 15,
		"comments":           4,
	}
	for table, want := range cases {
		var got int
		if err := conn.QueryRow("SELECT count(*) FROM " + table).Scan(&got); err != nil {
			t.Fatalf("count %s: %v", table, err)
		}
		if got != want {
			t.Errorf("%s: got %d rows, want %d", table, got, want)
		}
	}
}

// TestUuid16RoundTrip is A6 for the Uuid16 column encoding: the hex form the
// API exposes must recover exactly from the 16 stored bytes.
func TestUuid16RoundTrip(t *testing.T) {
	conn := openReference(t)
	ids := loadReferenceIDs(t)

	rows, err := conn.Query(
		"SELECT id, root_conversation_id, parent_conversation_id FROM conversations")
	if err != nil {
		t.Fatalf("query conversations: %v", err)
	}
	defer rows.Close()

	seen := 0
	for rows.Next() {
		var rawID, rawRoot []byte
		var rawParent []byte
		if err := rows.Scan(&rawID, &rawRoot, &rawParent); err != nil {
			t.Fatalf("scan conversation: %v", err)
		}
		id, err := db.ScanBlob(rawID)
		if err != nil {
			t.Fatalf("decode id: %v", err)
		}
		if len(id.String()) != 32 {
			t.Errorf("id %q is not 32 hex chars", id.String())
		}
		root, err := db.ScanBlob(rawRoot)
		if err != nil {
			t.Fatalf("decode root id: %v", err)
		}
		if rawParent == nil {
			// A root conversation points at itself; a child points at its root.
			if id != root {
				t.Errorf("root conversation %s has root_id %s, want itself", id, root)
			}
		} else {
			parent, err := db.ScanBlob(rawParent)
			if err != nil {
				t.Fatalf("decode parent id: %v", err)
			}
			if parent.IsZero() {
				t.Error("parent id decoded to zero for a child conversation")
			}
			// The child's root is the conversation it descends from.
			if root != parent {
				t.Errorf("child %s: root_id %s != parent_id %s", id, root, parent)
			}
		}
		seen++
	}
	if err := rows.Err(); err != nil {
		t.Fatalf("iterate conversations: %v", err)
	}
	if seen != 4 {
		t.Fatalf("scanned %d conversations, want 4", seen)
	}

	// The generator's ids must survive the round trip: this is what lets the
	// API keep serving the same URLs after the rewrite.
	for name, want := range ids.Conversations {
		parsed, err := db.ParseUuid16(want)
		if err != nil {
			t.Fatalf("%s: parse seeded id %q: %v", name, want, err)
		}
		if parsed.String() != strings.ToLower(want) {
			t.Errorf("%s: round trip gave %q, want %q", name, parsed.String(), want)
		}
	}
}

// TestCompressedTextFrames is A6 for CompressedText: both framed variants and
// both legacy variants must decode to the plaintext Python wrote.
func TestCompressedTextFrames(t *testing.T) {
	conn := openReference(t)

	rows, err := conn.Query("SELECT kind, description FROM agents ORDER BY kind")
	if err != nil {
		t.Fatalf("query agents: %v", err)
	}
	defer rows.Close()

	var sawZstd, sawRaw bool
	for rows.Next() {
		var kind int64
		var raw any
		if err := rows.Scan(&kind, &raw); err != nil {
			t.Fatalf("scan agent: %v", err)
		}
		blob, ok := raw.([]byte)
		if !ok {
			t.Fatalf("kind %d: description arrived as %T, want []byte", kind, raw)
		}
		if len(blob) < 2 || blob[0] != 0x00 {
			t.Fatalf("kind %d: missing frame sentinel in %v", kind, blob[:min(4, len(blob))])
		}
		switch blob[1] {
		case 0x01:
			sawZstd = true
		case 0x00:
			sawRaw = true
		default:
			t.Fatalf("kind %d: unexpected codec 0x%02x", kind, blob[1])
		}

		text, err := db.DecodeCompressedText(raw)
		if err != nil {
			t.Fatalf("kind %d: decode: %v", kind, err)
		}
		if text == "" {
			t.Errorf("kind %d: decoded to empty text", kind)
		}
		if kind == db.AgentKind["user"] && text != "short" {
			t.Errorf("kind %d: got %q, want %q", kind, text, "short")
		}
		if kind == db.AgentKind["server"] && !strings.Contains(text, "\"note\"") {
			t.Errorf("kind %d: decoded text is not the JSON the generator wrote: %q",
				kind, text[:min(60, len(text))])
		}
	}
	if err := rows.Err(); err != nil {
		t.Fatalf("iterate agents: %v", err)
	}
	if !sawZstd {
		t.Error("no zstd-framed value in the fixture; the generator changed")
	}
	if !sawRaw {
		t.Error("no raw-framed value in the fixture; the generator changed")
	}
}

// TestCompressedTextLegacyPassThrough covers the rows a pre-migration database
// still holds: unframed plaintext as TEXT and as BLOB must come back verbatim,
// alongside the framed variants. The fixture stores all four on comments.body,
// which is a real CompressedText column -- putting them on a plain JSON column
// would exercise the decoder with data the app never writes.
func TestCompressedTextLegacyPassThrough(t *testing.T) {
	conn := openReference(t)

	rows, err := conn.Query("SELECT id, body FROM comments ORDER BY id")
	if err != nil {
		t.Fatalf("query comments: %v", err)
	}
	defer rows.Close()

	var sawFramedZstd, sawFramedRaw, sawLegacyText, sawLegacyBlob bool
	seen := 0
	for rows.Next() {
		var id string
		var raw any
		if err := rows.Scan(&id, &raw); err != nil {
			t.Fatalf("scan comment: %v", err)
		}
		text, err := db.DecodeCompressedText(raw)
		if err != nil {
			t.Fatalf("comment %s: decode %T: %v", id, raw, err)
		}
		if text == "" {
			t.Errorf("comment %s decoded to empty text", id)
		}

		switch value := raw.(type) {
		case string:
			sawLegacyText = true
			if text != value {
				t.Errorf("comment %s: legacy TEXT changed: %q -> %q", id, value, text)
			}
		case []byte:
			if len(value) == 0 {
				t.Errorf("comment %s: empty blob", id)
				continue
			}
			if value[0] != 0x00 {
				sawLegacyBlob = true
				if text != string(value) {
					t.Errorf("comment %s: legacy BLOB changed: %q -> %q", id, value, text)
				}
				break
			}
			switch value[1] {
			case 0x01:
				sawFramedZstd = true
			case 0x00:
				sawFramedRaw = true
			}
		default:
			t.Fatalf("comment %s arrived as %T", id, raw)
		}
		seen++
	}
	if err := rows.Err(); err != nil {
		t.Fatalf("iterate comments: %v", err)
	}

	if seen != 4 {
		t.Fatalf("scanned %d comments, want 4 (one per storage variant)", seen)
	}
	for name, ok := range map[string]bool{
		"framed zstd": sawFramedZstd,
		"framed raw":  sawFramedRaw,
		"legacy TEXT": sawLegacyText,
		"legacy BLOB": sawLegacyBlob,
	} {
		if !ok {
			t.Errorf("fixture is missing the %s variant", name)
		}
	}
}

// TestEnumCodesMatchDump is A6 for the SMALLINT codes: the generated Go tables
// must equal the Python dump exactly, including codes that are reserved but
// not yet written.
func TestEnumCodesMatchDump(t *testing.T) {
	raw, err := os.ReadFile(enumDump)
	if err != nil {
		t.Fatalf("read %s: %v", enumDump, err)
	}
	var dump map[string]map[string]int64
	if err := json.Unmarshal(raw, &dump); err != nil {
		t.Fatalf("parse %s: %v", enumDump, err)
	}

	goTables := map[string]map[string]int64{
		"conversation_kind":               db.ConversationKind,
		"item_type":                       db.ItemType,
		"item_status":                     db.ItemStatus,
		"comment_status":                  db.CommentStatus,
		"session_live_status":             db.SessionLiveStatus,
		"account_token_kind":              db.AccountTokenKind,
		"policy_type":                     db.PolicyType,
		"policy_scope":                    db.PolicyScope,
		"device_grant_status":             db.DeviceGrantStatus,
		"host_status":                     db.HostStatus,
		"agent_kind":                      db.AgentKind,
		"scheduled_task_state":            db.ScheduledTaskState,
		"scheduled_task_execution_target": db.ScheduledTaskExecutionTarget,
		"scheduled_task_session_mode":     db.ScheduledTaskSessionMode,
		"scheduled_task_run_status":       db.ScheduledTaskRunStatus,
	}

	if len(dump) != len(goTables) {
		t.Fatalf("dump has %d enum tables, Go has %d", len(dump), len(goTables))
	}
	for table, wantCodes := range dump {
		goTable, ok := goTables[table]
		if !ok {
			t.Errorf("%s: present in dump but not in Go", table)
			continue
		}
		if len(wantCodes) != len(goTable) {
			t.Errorf("%s: dump has %d codes, Go has %d", table, len(wantCodes), len(goTable))
		}
		for name, want := range wantCodes {
			got, ok := goTable[name]
			if !ok {
				t.Errorf("%s: %q missing from Go table", table, name)
				continue
			}
			if got != want {
				t.Errorf("%s: %q = %d in Go, %d in Python", table, name, got, want)
			}
		}
	}
}

// TestStoredEnumCodesDecode checks the codes actually present in the fixture,
// which is what a reader hits first: a renumbered code would surface here
// rather than only in the dump comparison.
func TestStoredEnumCodesDecode(t *testing.T) {
	conn := openReference(t)

	rows, err := conn.Query("SELECT DISTINCT type FROM conversation_items")
	if err != nil {
		t.Fatalf("query item types: %v", err)
	}
	defer rows.Close()

	seen := map[string]bool{}
	for rows.Next() {
		var code int64
		if err := rows.Scan(&code); err != nil {
			t.Fatalf("scan type: %v", err)
		}
		name, err := db.DecodeName(db.ItemTypeName, "conversation_items.type", code)
		if err != nil {
			t.Errorf("stored item type %d is unknown to the Go codec: %v", code, err)
			continue
		}
		seen[name] = true
	}
	if err := rows.Err(); err != nil {
		t.Fatalf("iterate item types: %v", err)
	}

	// The generator writes one row per ITEM_TYPE value, so every one must
	// appear. A gap means either the generator or the codec changed.
	for name := range db.ItemType {
		if !seen[name] {
			t.Errorf("item type %q has no row in the fixture", name)
		}
	}
}
